/bin/zsh -lc "python -c 'import pandas as pd; from analysis import fit_quadratic_trend; d=pd.DataFrame({\"year\":[2000,2001,2002],\"latitude\":[1.,1.,1.],\"longitude\":[2.,2.,2.],\"air_temperature\":[1.,2.,3.]});
